target.css:
:root {
  --ink: #27312e;
  --muted: #68736d;
  --paper: #fffdf8;
  --line: #dce3d8;
  --cream: #f5ead6;
  --orange: #d96c39;
  --orange-dark: #b85027;
  --mint: #dcefe2;
}

.dial-card {
  width: 480px;
  box-sizing: border-box;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.dial-header {
  display: flex;
  align-items: center;
  gap: 11px;
}

.coffee-mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 13px;
  background: var(--cream);
  font-size: 22px;
}

.title-block {
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.ready-badge {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
}

.recipe-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 15px;
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

.reading {
  padding: 11px 14px;
  border-right: 1px solid var(--line);
}

.reading:last-child {
  border-right: 0;
}

.reading-label {
  display: block;
  margin-bottom: 3px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.reading strong {
  font-size: 21px;
  line-height: 1;
}

.reading strong span {
  margin-left: 2px;
  color: var(--muted);
  font-size: 12px;
}

.dial-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 13px;
}

.dial-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--orange);
}

.actions {
  display: flex;
  gap: 7px;
}

button {
  padding: 7px 10px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}

.secondary-button {
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
}

.primary-button {
  border: 1px solid var(--orange-dark);
  background: var(--orange);
  color: var(--paper);
}

